WORKING_ROLES = ("Engineer", "QA", "Clinical Safety Officer")
ROLE_ORDER = WORKING_ROLES + ("Device admin",)
ALL_DEVICES = "All-device access"


def roles_to_teams(apps, schema_editor):
    """
    Roles move from the person to each of their device teams.

    Before 0004 a role (an auth Group) applied on every team the person was on. Each active
    membership now gets the person's roles, so nobody gains or loses a permission. The person
    then stops holding those roles organisation-wide, unless they have All-device access (for
    example a head of quality), whose roles stay organisation-wide. People on no team keep
    their groups. Each device also gets a Device admin: its QA members, or else its first
    member, so every team can be managed.
    """
    Group = apps.get_model("auth", "Group")
    User = apps.get_model("auth", "User")
    Membership = apps.get_model("qms", "DeviceMembership")
    Group.objects.get_or_create(name="Device admin")
    for user in User.objects.all():
        roles = set(user.groups.filter(name__in=WORKING_ROLES).values_list("name", flat=True))
        memberships = Membership.objects.filter(user=user, active=True)
        if not memberships.exists():
            continue
        for m in memberships:
            m.roles = ", ".join(r for r in ROLE_ORDER if r in roles)
            m.save(update_fields=["roles"])
        if not user.groups.filter(name=ALL_DEVICES).exists():
            user.groups.remove(*Group.objects.filter(name__in=WORKING_ROLES))
    Device = apps.get_model("qms", "Device")
    for device in Device.objects.all():
        team = list(Membership.objects.filter(device=device, active=True).order_by("pk"))
        admins = [m for m in team if "QA" in m.roles] or team[:1]
        for m in admins:
            held = {r.strip() for r in m.roles.split(",") if r.strip()} | {"Device admin"}
            m.roles = ", ".join(r for r in ROLE_ORDER if r in held)
            m.save(update_fields=["roles"])


